1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	
10	/**
11	 * Shared, deterministic household identity for the create-owner pipeline.
12	 *
13	 * <p>An owner's household is keyed purely on its last name and postcode: the {@code householdId} is
14	 * the first 12 hex characters (upper-case) of SHA-256 over {@code normalizedLastName + "|" +
15	 * postcode}. Because it is derived from nothing but those two values, every owner with the same last
16	 * name and postcode receives the same identifier automatically — no owner has to opt in, and the id
17	 * is identical before and after the owner is saved.
18	 *
19	 * <p>The last name is normalized (trimmed, internal whitespace collapsed, lower-cased) so that
20	 * cosmetic differences do not split a household; the postcode is compared as its trimmed value.
21	 *
22	 * <p>Used by {@link AssignHousehold} (which stores the id on the new owner), by
23	 * {@link CheckOwnerIdentityUnique} (which rejects a second owner already in the household unless the
24	 * request declares {@code sharesHousehold}) and by {@link OwnerIdentityKey}.
25	 */
26	final class Household {
27	
28	    private Household() {
29	    }
30	
31	    /** The deterministic household id the given create-owner request belongs to. */
32	    static String idFor(OwnerFieldsDto request) {
33	        return deriveId(normalizeName(request.getLastName()), normalizePostcode(request.getPostcode()));
34	    }
35	
36	    /** The deterministic household id an existing, stored owner belongs to. */
37	    static String idFor(Owner owner) {
38	        return deriveId(normalizeName(owner.getLastName()), normalizePostcode(owner.getPostcode()));
39	    }
40	
41	    /**
42	     * Whether the request declares itself a member of a shared household. This only bypasses the
43	     * duplicate block (see {@link CheckOwnerIdentityUnique}); it never affects which household id an
44	     * owner is assigned, which is fixed by its last name and postcode.
45	     */
46	    static boolean sharesHousehold(OwnerFieldsDto request) {
47	        return Boolean.TRUE.equals(request.getSharesHousehold());
48	    }
49	
50	    /** First 12 upper-hex characters of SHA-256 over {@code lastName + "|" + postcode}. */
51	    private static String deriveId(String lastName, String postcode) {
52	        try {
53	            byte[] digest = MessageDigest.getInstance("SHA-256")
54	                    .digest((lastName + "|" + postcode).getBytes(StandardCharsets.UTF_8));
