package org.springframework.samples.petclinic.util;

import java.time.LocalDate;
import java.time.temporal.ChronoUnit;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Derives an owner's numeric {@code membershipLevel} (1 to 4) from its stored fields. Levels 1 to 3
 * come from values captured at creation: the level starts at 1, gains 1 when the owner has an email,
 * gains 1 when its {@code namesakeCount} is 0, and is capped at 3 before tenure is considered. Level
 * 4 is reserved for tenure: an owner already at that cap advances to 4 only once its tenure — the
 * days from its {@code registrationDate} to today — exceeds 365. A newly created owner has zero
 * tenure, so it never exceeds level 3.
 */
public final class MembershipLevel {

    /** The lowest level every owner starts at. */
    private static final int BASE = 1;

    /** The highest level awarded from creation-time fields, before tenure is considered. */
    private static final int PRE_TENURE_CAP = 3;

    /** The highest level this rule may award; reaching it requires tenure. */
    private static final int CAP = 4;

    /** Tenure, in days, that an owner must exceed to reach level 4. */
    private static final long TENURE_DAYS = 365;

    private MembershipLevel() {
    }

    /** Returns the membership level (1 to 4) for {@code owner} from its stored fields. */
    public static int levelOf(Owner owner) {
        int level = BASE;
        String email = owner.getEmail();
        if (email != null && !email.isEmpty()) {
            level++;
        }
        Integer namesakeCount = owner.getNamesakeCount();
        if (namesakeCount != null && namesakeCount == 0) {
            level++;
        }
        level = Math.min(level, PRE_TENURE_CAP);
        if (level == PRE_TENURE_CAP && exceedsTenure(owner.getRegistrationDate())) {
            level = CAP;
        }
        return level;
    }

    /** Whether {@code registrationDate} is more than {@value #TENURE_DAYS} days before today. */
    private static boolean exceedsTenure(LocalDate registrationDate) {
        if (registrationDate == null) {
            return false;
        }
        return ChronoUnit.DAYS.between(registrationDate, LocalDate.now()) > TENURE_DAYS;
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Shared, deterministic household identity for the create-owner pipeline.
 *
 * <p>An owner's household is keyed purely on its last name and postcode: the {@code householdId} is
 * the first 12 hex characters (upper-case) of SHA-256 over {@code normalizedLastName + "|" +
 * postcode}. Because it is derived from nothing but those two values, every owner with the same last
 * name and postcode receives the same identifier automatically — no owner has to opt in, and the id
 * is identical before and after the owner is saved.
 *
 * <p>The last name is normalized (trimmed, internal whitespace collapsed, lower-cased) so that
 * cosmetic differences do not split a household; the postcode is compared as its trimmed value.
 *
 * <p>Used by {@link AssignHousehold} (which stores the id on the new owner), by
 * {@link CheckOwnerIdentityUnique} (which rejects a second owner already in the household unless the
 * request declares {@code sharesHousehold}) and by {@link OwnerIdentityKey}.
 */
final class Household {

    private Household() {
    }

    /** The deterministic household id the given create-owner request belongs to. */
    static String idFor(OwnerFieldsDto request) {
        return deriveId(normalizeName(request.getLastName()), normalizePostcode(request.getPostcode()));
    }

    /** The deterministic household id an existing, stored owner belongs to. */
    static String idFor(Owner owner) {
        return deriveId(normalizeName(owner.getLastName()), normalizePostcode(owner.getPostcode()));
    }

    /**
     * Whether the request declares itself a member of a shared household. This only bypasses the
     * duplicate block (see {@link CheckOwnerIdentityUnique}); it never affects which household id an
     * owner is assigned, which is fixed by its last name and postcode.
     */
    static boolean sharesHousehold(OwnerFieldsDto request) {
        return Boolean.TRUE.equals(request.getSharesHousehold());
    }

    /** First 12 upper-hex characters of SHA-256 over {@code lastName + "|" + postcode}. */
    private static String deriveId(String lastName, String postcode) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                    .digest((lastName + "|" + postcode).getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(12);
            for (int i = 0; i < 6; i++) {
                sb.append(String.format("%02X", digest[i]));
            }
            return sb.toString();
        }
        catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException("SHA-256 unavailable", ex);
        }
    }

    /** Lower-case and collapse all runs of whitespace to a single space, trimmed. */
    private static String normalizeName(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase();
    }

    /** Trimmed postcode, or empty when none is supplied. */
    private static String normalizePostcode(String postcode) {
        return (postcode == null) ? "" : postcode.trim();
    }
}

